/* Runtime for code generated by tools-phase2/hex2c.py: memory access through the `m` (const GuestMem *) in scope. Development
 * stage only: uses GNU statement expressions. */
#ifndef HEX2C_RT_H
#define HEX2C_RT_H

#include <stdbool.h>
#include "guest_mem.h"

#define RD8(a)   ((uint8_t)m->rd8(m->ctx, (uint32_t)(a)))
#define RDS8(a)  ((int8_t)m->rd8(m->ctx, (uint32_t)(a)))
#define RD16(a)  ((uint16_t)m->rd16(m->ctx, (uint32_t)(a)))
#define RDS16(a) ((int16_t)m->rd16(m->ctx, (uint32_t)(a)))
#define RD32(a)  ((uint32_t)m->rd32(m->ctx, (uint32_t)(a)))

static inline uint8_t  hx_w8(const GuestMem *m, uint32_t a, uint8_t v)   { m->wr8(m->ctx, a, v); return v; }
static inline uint16_t hx_w16(const GuestMem *m, uint32_t a, uint16_t v) { m->wr16(m->ctx, a, v); return v; }
static inline uint32_t hx_w32(const GuestMem *m, uint32_t a, uint32_t v) { m->wr32(m->ctx, a, v); return v; }
#define WR8(a, v)  hx_w8(m, (uint32_t)(a), (uint8_t)(v))
#define WR16(a, v) hx_w16(m, (uint32_t)(a), (uint16_t)(v))
#define WR32(a, v) hx_w32(m, (uint32_t)(a), (uint32_t)(v))

/* read-modify-write: HX_RMW<bits>(addr, op, rhs, S|U); the address is evaluated once, the stored value is the result */
#define HX_RD8_S(a)  RDS8(a)
#define HX_RD8_U(a)  RD8(a)
#define HX_RD16_S(a) RDS16(a)
#define HX_RD16_U(a) RD16(a)
#define HX_RD32_S(a) ((int32_t)RD32(a))
#define HX_RD32_U(a) RD32(a)
#define HX_RMW8(a, op, rhs, sg)  ({ uint32_t _a = (uint32_t)(a); uint8_t  _v = (uint8_t)(HX_RD8_##sg(_a) op (rhs));  m->wr8(m->ctx, _a, _v);  _v; })
#define HX_RMW16(a, op, rhs, sg) ({ uint32_t _a = (uint32_t)(a); uint16_t _v = (uint16_t)(HX_RD16_##sg(_a) op (rhs)); m->wr16(m->ctx, _a, _v); _v; })
#define HX_RMW32(a, op, rhs, sg) ({ uint32_t _a = (uint32_t)(a); uint32_t _v = (uint32_t)(HX_RD32_##sg(_a) op (rhs)); m->wr32(m->ctx, _a, _v); _v; })

#endif
